#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Play together's accounts. Safe to re-run: every stage keeps what's done.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8
cd "$(dirname "$0")"

# Gradle reads these when building the app; the signing key's settings already live here.
ENV_FILE="$HOME/.gradle/gradle.properties"
PACKAGE="com.skylightlim.umpoint"

[[ -d node_modules ]] || npm install --no-audit --no-fund

banner "UMPoint Badminton: Play together setup"

stage "Cloudflare: which account"
say "The server runs on Cloudflare's free plan. Check this is the account you want."
npx wrangler whoami 2>&1 | grep -iE 'associated with the email|account name|not authenticated' || true
if ! confirm "Use this account? (No stops here so you can run: npx wrangler login)"; then
  exit 1
fi

stage "Cloudflare: database and server"
say "Creates the database, applies the tables and publishes the worker."
note "It holds emails, names and session plans. It never sees a UMPoint session."
confirm "Create and publish them now?" || exit 1
d1_id() { npx wrangler d1 list --json | python3 -c "import json,sys;print(next((d['uuid'] for d in json.load(sys.stdin) if d['name']=='umpoint-together'),''))"; }
DB_ID=$(d1_id)
if [[ -z "$DB_ID" ]]; then
  npx wrangler d1 create umpoint-together >/dev/null
  DB_ID=$(d1_id)
fi
[[ -n "$DB_ID" ]] || { warn "Couldn't find the database after creating it."; exit 1; }
sed -i -E "s/(\"database_name\": \"umpoint-together\", \"database_id\": \")[^\"]*/\1$DB_ID/" wrangler.jsonc
npx wrangler d1 migrations apply DB --remote
DEPLOY_LOG=$(npx wrangler deploy 2>&1) || { printf '%s\n' "$DEPLOY_LOG"; exit 1; }
SERVER_URL=$(printf '%s\n' "$DEPLOY_LOG" | grep -oE 'https://[^ ]+\.workers\.dev' | head -n1)
[[ -n "$SERVER_URL" ]] || ask SERVER_URL "Paste the workers.dev address wrangler printed:"
write_env UMPOINT_TOGETHER_URL "$SERVER_URL"
pause "Press Enter to continue"

stage "Firebase: create the project"
say "Firebase carries the notifications. Sending them is free."
open_url "https://console.firebase.google.com/"
step "Create a new Firebase project, named umpoint-badminton or anything you like."
step "Google Analytics isn't needed, so turn it off if asked."
pause "Press Enter when the project exists"

stage "Firebase: register the app"
step "On the project's home page, add an app and choose Android."
step "Package name, exactly: $PACKAGE"
step "Download google-services.json when offered. Skip the remaining steps of that dialog."
note "This app reads the file's values into the build, so the file stays out of the repo."
ask GOOGLE_SERVICES "Path to google-services.json [~/Downloads/google-services.json]:"
GOOGLE_SERVICES="${GOOGLE_SERVICES:-$HOME/Downloads/google-services.json}"
GOOGLE_SERVICES="${GOOGLE_SERVICES/#\~/$HOME}"
FIREBASE_VALUES=$(python3 - "$GOOGLE_SERVICES" "$PACKAGE" <<'PY'
import json, sys
config = json.load(open(sys.argv[1]))
client = next(c for c in config["client"] if c["client_info"]["android_client_info"]["package_name"] == sys.argv[2])
print(client["client_info"]["mobilesdk_app_id"])
print(client["api_key"][0]["current_key"])
print(config["project_info"]["project_id"])
print(config["project_info"]["project_number"])
PY
) || { warn "That file has no app with the package $PACKAGE. Check the package name and run this again."; exit 1; }
{ read -r FIREBASE_APP_ID; read -r FIREBASE_API_KEY; read -r FIREBASE_PROJECT; read -r FIREBASE_SENDER; } <<< "$FIREBASE_VALUES"
write_env UMPOINT_FIREBASE_APP_ID "$FIREBASE_APP_ID"
write_env UMPOINT_FIREBASE_API_KEY "$FIREBASE_API_KEY"
write_env UMPOINT_FIREBASE_PROJECT_ID "$FIREBASE_PROJECT"
write_env UMPOINT_FIREBASE_SENDER_ID "$FIREBASE_SENDER"
pause "Press Enter to continue"

stage "Firebase: let the server send notifications"
open_url "https://console.firebase.google.com/project/$FIREBASE_PROJECT/settings/serviceaccounts/adminsdk"
step "On the Service accounts tab, click Generate new private key and confirm."
warn "That file can send as your project, so it must never enter the repo."
ask SERVICE_ACCOUNT_FILE "Path to the downloaded .json file:"
SERVICE_ACCOUNT_FILE="${SERVICE_ACCOUNT_FILE/#\~/$HOME}"
[[ -f "$SERVICE_ACCOUNT_FILE" ]] || { warn "No file at $SERVICE_ACCOUNT_FILE."; exit 1; }
python3 -c "import json,sys;d=json.load(open(sys.argv[1]));assert d['type']=='service_account' and d['project_id']==sys.argv[2]" "$SERVICE_ACCOUNT_FILE" "$FIREBASE_PROJECT" \
  || { warn "That isn't this project's service account file."; exit 1; }
# Compacted to one line, as the secret is parsed whole.
python3 -c "import json,sys;print(json.dumps(json.load(open(sys.argv[1]))))" "$SERVICE_ACCOUNT_FILE" | npx wrangler secret put FIREBASE_SERVICE_ACCOUNT
if confirm "The worker has it now. Delete the downloaded copy?"; then
  rm -- "$SERVICE_ACCOUNT_FILE"
  say "Deleted."
fi
pause "Press Enter to continue"

stage "Google: sign-in screen"
say "Firebase made a Google Cloud project. The sign-in screen lives there."
open_url "https://console.cloud.google.com/auth/overview?project=$FIREBASE_PROJECT"
step "If it says it isn't configured, click Get started."
step "App name UMPoint Badminton, your email for support and contact, audience External."
step "On the Audience page, click Publish app so it leaves Testing."
note "Testing mode only admits listed test users. Only email and profile are requested,"
note "which are non-sensitive scopes, so Google shouldn't require a review for this."
note "Menu names here may have moved. If a step doesn't match, look for the same words nearby."
pause "Press Enter when the app is published"

stage "Google: sign-in keys"
open_url "https://console.cloud.google.com/auth/clients/create?project=$FIREBASE_PROJECT"
step "Application type: Web application. Name: Play together server."
step "Add this under Authorized redirect URIs, exactly:"
printf '\n      %s%s/auth/callback%s\n\n' "$BOLD" "$SERVER_URL" "$RESET"
step "Create it, and copy the Client ID and Client secret it shows."
ask GOOGLE_CLIENT_ID "Paste the Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret (hidden):"
printf '%s' "$GOOGLE_CLIENT_ID" | npx wrangler secret put GOOGLE_CLIENT_ID
printf '%s' "$GOOGLE_CLIENT_SECRET" | npx wrangler secret put GOOGLE_CLIENT_SECRET
pause "Press Enter to continue"

stage "Check it works"
sleep 5
STATE_CODE=$(curl -s -m 15 -o /dev/null -w '%{http_code}' "$SERVER_URL/state" || true)
START_TARGET=$(curl -s -m 15 -o /dev/null -w '%{redirect_url}' "$SERVER_URL/auth/start?state=check" || true)
DEV_CODE=$(curl -s -m 15 -o /dev/null -w '%{http_code}' -X POST -d '{}' "$SERVER_URL/auth/dev" || true)
[[ "$STATE_CODE" == 401 ]] && say "✓ The server refuses requests without a sign-in." || warn "/state answered $STATE_CODE, expected 401."
[[ "$DEV_CODE" == 401 ]] && say "✓ The test-only sign-in is off." || warn "/auth/dev answered $DEV_CODE, expected 401. Don't use this server until that's fixed."
if [[ "$START_TARGET" == https://accounts.google.com/* && "$START_TARGET" == *"$GOOGLE_CLIENT_ID"* ]]; then
  say "✓ Sign-in goes to Google with your client."
else
  warn "Sign-in didn't go to Google with your client: $START_TARGET"
fi
step "Open this on your phone, and sign in with SiswaMail:"
printf '\n      %s%s/auth/start?state=check%s\n\n' "$BOLD" "$SERVER_URL" "$RESET"
note "You should land on a page saying you can go back to the app. If Google says"
note "the app is blocked by your organisation, UM's admins don't allow it, and Play"
note "together needs another way to sign in. Nothing else about the app is affected."
pause "Press Enter to finish"

finish
say "Rebuild the app so it picks up the new values: ./gradlew :app:assembleRelease"
